INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dashboard-top-client-ips', 'dashboard', 'qgw', 'SELECT client_ip AS client_ip, SUM( sessions) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_client_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY client_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the client''s IP address. The ${metric} variable includes three options: sessions, bytes, and packets.','2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dashboard-top-server-ips', 'dashboard', 'qgw', 'SELECT server_ip AS server_ip, SUM( sessions) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_server_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY server_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the server IP address. The ${metric} variable includes three options: sessions, bytes, and packets.','2023-08-19 00:00:00', '2023-08-19 00:00:00');
