INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Optimizer', 'trouble-shooting', 'qgw', 'SELECT client_ip AS client_ip, count(*) AS count, sum(sent_bytes + received_bytes) / 1024 / 1024 AS bytes_MB FROM session_record WHERE recv_time >= toDateTime(UNIX_TIMESTAMP(''${start}'')) AND recv_time < toDateTime(UNIX_TIMESTAMP(''${end}'')) GROUP BY client_ip ORDER BY count DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('IP_TO_GEO、IP_TO_ISP-function-verify', 'trouble-shooting', 'qgw', 'SELECT IP_TO_GEO(client_ip) AS geo, IP_TO_ISP(client_ip) AS isp FROM session_record LIMIT 1', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('ISO 8601(clickhouse)', 'trouble-shooting', 'qgw', 'SELECT FROM_UNIXTIME(UNIX_TIMESTAMP(''2023-02-08T00:00:00+0800'')) FROM session_record limit 1', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Query-with-time-range', 'trouble-shooting', 'hbase', 'SELECT last_update_time FROM relation_account_framedip WHERE last_update_time>=CAST(TO_TIMESTAMP(''${end}'',''yyyy-MM-dd HH:mm:ss'',''Asia/Shanghai'') AS UNSIGNED_LONG) AND last_update_time<CAST(TO_TIMESTAMP (''${end}'',''yyyy-MM-dd HH:mm:ss'',''Asia/Shanghai'') AS UNSIGNED_LONG) LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Query-with-primary-key', 'trouble-shooting', 'hbase', 'select * from relation_account_framedip where ROWKEY = ''0a771a381088e7d72ded13e998c06cbe'' limit 1', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
